import java.util.*;

List<Integer> imm = List.of(1, 2, 3);
try {
    imm.add(4);
} catch (UnsupportedOperationException e) {
    System.out.println("add(): " + e);
}
try {
    imm.set(0, 99);
} catch (UnsupportedOperationException e) {
    System.out.println("set(): " + e);
}

Map<String, Integer> immMap = Map.of("a", 1, "b", 2);
try {
    immMap.put("c", 3);
} catch (UnsupportedOperationException e) {
    System.out.println("Map put(): " + e);
}
